use std::collections::HashMap;
use std::sync::Arc;

use axum::extract::State;
use axum::http::{header, HeaderMap, StatusCode};
use axum::routing::get;
use axum::{Json, Router};
use serde::Serialize;

#[derive(Clone, Serialize)]
struct CurrentUser {
    id: u64,
    name: String,
}

#[derive(Clone)]
struct AppState {
    tokens: Arc<HashMap<String, CurrentUser>>,
}

fn authenticate(state: &AppState, headers: &HeaderMap) -> Result<CurrentUser, StatusCode> {
    let token = headers
        .get(header::AUTHORIZATION)
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.strip_prefix("Bearer "))
        .ok_or(StatusCode::UNAUTHORIZED)?;
    state.tokens.get(token).cloned().ok_or(StatusCode::UNAUTHORIZED)
}

async fn me(
    State(state): State<AppState>,
    headers: HeaderMap,
) -> Result<Json<CurrentUser>, StatusCode> {
    let user = authenticate(&state, &headers)?;
    Ok(Json(user))
}

async fn orders(State(state): State<AppState>, headers: HeaderMap) -> Result<String, StatusCode> {
    let user = authenticate(&state, &headers)?;
    Ok(format!("orders of {}", user.id))
}

async fn health() -> &'static str {
    "ok"
}

#[tokio::main]
async fn main() {
    let state = AppState {
        tokens: Arc::new(HashMap::new()),
    };
    let app = Router::new()
        .route("/health", get(health))
        .route("/me", get(me))
        .route("/orders", get(orders))
        .with_state(state);
    let listener = tokio::net::TcpListener::bind("0.0.0.0:3000").await.unwrap();
    axum::serve(listener, app).await.unwrap();
}

